\foreach \x/\m in {1/Jan,2/Feb,3/Mar,4/Apr,5/May,6/Jun,7/Jul,8/Aug} \node[below,font=\scriptsize] at (\x,0) {\m};
\foreach \y/\v in {1/7.00,2/8.00,3/9.00,4/10.00,5/11.00} \node[left,font=\small] at (0,\y) {\v};
\node[below left,font=\small] at (0,0) {$0$};
\draw[very thick,blue] (1,2.0) -- (2,2.8) -- (3,3.5) -- (4,4.2) -- (5,5.2) -- (6,4.5) -- (7,3.8) -- (8,4.5);
\foreach \pt in {(1,2.0),(2,2.8),(3,3.5),(4,4.2),(5,5.2),(6,4.5),(7,3.8),(8,4.5)} \fill[blue] \pt circle (2.5pt);
\end{tikzpicture}
[/tikz]
In which month did the share price reach its peak, and what was that peak price?

